// a bundle is a "phigros++ <native> <version> <game>..." line, then "<path>\n<size>\n<bytes>" per file. a downloaded
// one (phigros++/bundle) runs only signed by the release key, for this app and game, and newer than the built-in one
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "bundle.h"  // generated by scripts/build-lib.sh: builtin[] (the bundle, zero terminated) and release_key[]
#include "lauxlib.h"
#include "phigrospp.h"
#include "tweetnacl.h"

static long running;  // the version of the bundle in use, as a number

// "1.2.3" as 1002003, 0 when it isn't a version
static long number(const char *version) {
  unsigned a, b, c;
  char extra;
  return sscanf(version, "%u.%u.%u%c", &a, &b, &c, &extra) == 3 ? a * 1000000L + b * 1000L + c : 0;
}

// reads the header line and its version, and unless any is set, why the bundle can't run here (NULL when it can)
static const char *header(Bundle *b, char version[32], bool any) {
  const char *newline = memchr(b->at, '\n', b->end - b->at);
  char line[256], *save;
  if (!newline || newline - b->at >= (long)sizeof line) return "not a Phigros++ bundle";
  memcpy(line, b->at, newline - b->at);
  line[newline - b->at] = 0;
  b->at = newline + 1;
  char *magic = strtok_r(line, " ", &save), *native = strtok_r(NULL, " ", &save), *v = strtok_r(NULL, " ", &save);
  if (!v || strcmp(magic, "phigros++") || !number(v)) return "not a Phigros++ bundle";
  snprintf(version, 32, "%s", v);
  if (any) return NULL;
  if (atoi(native) != NATIVE) return "made for another app";
  for (char *game; (game = strtok_r(NULL, " ", &save));)
    if (!strcmp(game, GAME)) return NULL;
  return "made for other versions of the game";
}

bool next_file(Bundle *b, const char **path, size_t *path_size, const char **data, size_t *size) {
  const char *newline = memchr(b->at, '\n', b->end - b->at);
  if (!newline) return false;
  char *end;
  unsigned long n = strtoul(newline + 1, &end, 10);  // stops at the end, which is always followed by a zero
  if (end >= b->end || *end != '\n' || n > (size_t)(b->end - end - 1)) return false;
  *path = b->at, *path_size = newline - b->at, *data = end + 1, *size = n;
  b->at = end + 1 + n;
  return true;
}

// why a downloaded bundle can't replace the running one, NULL when it can: its files are then in b, read from a
// string left on the stack
static const char *check(lua_State *L, const char *data, size_t size, char version[32], Bundle *b) {
  unsigned char *message = malloc(size);
  unsigned long long n;
  bool valid = crypto_sign_open(message, &n, (const unsigned char *)data, size, release_key) == 0;
  if (valid) lua_pushlstring(L, (char *)message, n);
  free(message);
  if (!valid) return "wrong signature";
  const char *m = lua_tostring(L, -1);
  *b = (Bundle){m, m + n};
  const char *why = header(b, version, false);
  return why ? why : number(version) > running ? NULL : "not newer";
}

// check(data) -> the version of a downloaded bundle that can replace the running one, or nil and why not
static int l_check(lua_State *L) {
  size_t size;
  const char *data = luaL_checklstring(L, 1, &size);
  char version[32];
  Bundle b;
  const char *why = check(L, data, size, version, &b);
  lua_pushstring(L, why ? NULL : version);
  lua_pushstring(L, why);
  return 2;
}

// a require searcher for the bundle's mods, chunks named @bundle/mods/... so mods find their files with
// phigrospp.read. its upvalue is the bundle's files
static int search(lua_State *L) {
  static const char *const forms[] = {"mods/%s.lua", "mods/%s/init.lua"};
  const char *name = luaL_checkstring(L, 1);
  for (int i = 0; i < 2; i++) {
    const char *path = lua_pushfstring(L, forms[i], name);
    if (lua_getfield(L, lua_upvalueindex(1), path) == LUA_TSTRING) {
      size_t size;
      const char *source = lua_tolstring(L, -1, &size);
      const char *chunk = lua_pushfstring(L, "@bundle/%s", path);
      if (luaL_loadbufferx(L, source, size, chunk, "t") != LUA_OK) return lua_error(L);
      lua_pushstring(L, chunk + 1);
      return 2;
    }
    lua_pop(L, 2);
  }
  lua_pushfstring(L, "no built-in mod '%s'", name);
  return 1;
}

// the bundle to run: phigros++/bundle when it can replace the built-in one. sets version, app (the built-in
// version), native, game, check and bundle (its files by path) on the table on top of the stack
Bundle open_bundle(lua_State *L, const char *root) {
  char app[32], version[32], path[600];
  Bundle bundle = {builtin, builtin + sizeof builtin - 1};
  header(&bundle, app, true);
  running = number(app);
  snprintf(version, sizeof version, "%s", app);

  snprintf(path, sizeof path, "%s/bundle", root);
  FILE *f = fopen(path, "rb");
  if (f) {
    fseek(f, 0, SEEK_END);
    size_t size = ftell(f);
    char *data = malloc(size);
    rewind(f);
    size = fread(data, 1, size, f);
    fclose(f);
    int top = lua_gettop(L);
    Bundle downloaded;
    const char *why = check(L, data, size, version, &downloaded);
    free(data);
    if (why) {
      LOGE("%s: %s, running the built-in one", path, why);
      lua_settop(L, top);
      snprintf(version, sizeof version, "%s", app);
    } else {
      bundle = downloaded;
      running = number(version);
      luaL_ref(L, LUA_REGISTRYINDEX);  // keeps the string holding its files
    }
  }
  LOGI("Phigros++ %s, %s", version, running == number(app) ? "built in" : "downloaded");

  lua_pushstring(L, version);
  lua_setfield(L, -2, "version");
  lua_pushstring(L, app);
  lua_setfield(L, -2, "app");
  lua_pushinteger(L, NATIVE);
  lua_setfield(L, -2, "native");
  lua_pushstring(L, GAME);
  lua_setfield(L, -2, "game");
  lua_pushcfunction(L, l_check);
  lua_setfield(L, -2, "check");

  lua_newtable(L);
  Bundle files = bundle;
  const char *file, *data;
  size_t file_size, size;
  while (next_file(&files, &file, &file_size, &data, &size)) {
    lua_pushlstring(L, file, file_size);
    lua_pushlstring(L, data, size);
    lua_rawset(L, -3);
  }
  // third, after the searcher for files: phigros++/mods/ overrides the built-in mods
  lua_getglobal(L, "package");
  lua_getfield(L, -1, "searchers");
  for (int i = (int)lua_rawlen(L, -1); i >= 3; i--) {
    lua_rawgeti(L, -1, i);
    lua_rawseti(L, -2, i + 1);
  }
  lua_pushvalue(L, -3);
  lua_pushcclosure(L, search, 1);
  lua_rawseti(L, -2, 3);
  lua_pop(L, 2);
  lua_setfield(L, -2, "bundle");
  return bundle;
}
